def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    valid = remaining >= 0
    if not np.any(valid):
        return np.full_like(bins, -np.inf, dtype=float)
    utilization = 1.0 - (remaining / bins)
    mean_util = np.mean(utilization[valid])
    score = np.exp(-remaining) - np.exp(-((utilization - mean_util) ** 2))
    return np.where(valid, score, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, -remaining, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    valid = remaining >= 0
    if not np.any(valid):
        return np.full_like(bins, -np.inf, dtype=float)
    valid_remaining = remaining[valid]
    mean_rem = np.mean(valid_remaining)
    decay = np.exp(-remaining)
    gaussian_penalty = np.exp(-((remaining - mean_rem) ** 2) / (2.0 * (np.var(valid_remaining) + 1e-8)))
    score = decay * gaussian_penalty
    return np.where(valid, score, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    valid = remaining >= 0
    if not np.any(valid):
        return np.full_like(bins, -np.inf, dtype=float)
    valid_remaining = remaining[valid]
    std_rem = np.std(valid_remaining)
    log_penalty = -np.log(remaining + 1.0)
    modulation = np.tanh(remaining / (std_rem + 1e-8))
    score = log_penalty + modulation
    return np.where(valid, score, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    valid = remaining >= 0
    if not np.any(valid):
        return np.full_like(bins, -np.inf, dtype=float)
    median_bin = np.median(bins[valid])
    capacity_penalty = 1.0 / (1.0 + remaining)
    oscillation = np.cos(np.pi * (bins - median_bin) / (np.max(bins) - np.min(bins) + 1e-8))
    score = capacity_penalty + oscillation
    return np.where(valid, score, -np.inf)
